-- Agent document tools (create_document / update_document / fill_pdf_form):
-- binary files generated by the chat agent, owned per-user. Payload is stored
-- base64 in `data`; `textContent` keeps a plain-text rendering so read_document
-- and the Files page never have to decode the binary. See
-- crossmodel/document-generator.ts + generated-files.controller.ts.

-- CreateTable
CREATE TABLE "generated_files" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "chatId" TEXT,
    "filename" TEXT NOT NULL,
    "format" TEXT NOT NULL,
    "mimeType" TEXT NOT NULL,
    "size" INTEGER NOT NULL,
    "data" TEXT NOT NULL,
    "textContent" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "generated_files_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "generated_files_userId_idx" ON "generated_files"("userId");

-- AddForeignKey
ALTER TABLE "generated_files" ADD CONSTRAINT "generated_files_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
